+
+fn tensor_block_sort_key(name: &str) -> (usize, &str) {
+    let block = name
+        .strip_prefix("blk.")
+        .and_then(|rest| rest.split_once('.'))
+        .and_then(|(idx, _)| idx.parse::<usize>().ok())
+        .unwrap_or(usize::MAX);
+    (block, name)
+}
